1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("base premiums", () => {
6	    it("empty item list → premium 5 G (only the processing fee)", () => {
7	      const result = runScenario({
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      });
11	
12	      expect(result).toEqual({ results: [{ premium: 5 }] });
13	    });
14	    it.todo("a single sword → base premium 100 G, premium 115 G (100 + 10 first insurance + 5 fee)");
15	    it.todo("a single amulet → base premium 60 G, premium 71 G (60 + 6 + 5)");
16	    it.todo("a single staff → base premium 80 G, premium 93 G (80 + 8 + 5)");
17	    it.todo("a single potion → base premium 40 G, premium 49 G (40 + 4 + 5)");
18	    it.todo("a single rune (component) → base premium 25 G, premium 33 G (25 + 2.5 + 5, rounded up)");
19	    it.todo("a single moonstone (component) → base premium 25 G");
