34	    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
35	    it.todo("cursed sword with enchantment 5 → both surcharges apply");
36	    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
37	    it.todo("customer with 1 year with MHPCO → no loyalty discount");
38	    it.todo("a first insurance carries a 10 % initial assessment surcharge");
39	    it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
40	    it.todo("a 5 G processing fee is added to every premium");
