42	
43	  describe("modifier scope on multi-item policies", () => {
44	    it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");
45	    it.todo("policy-wide modifiers apply to the sum of all item base premiums, the fee is added last");
46	  });
47	
48	  describe("rounding in the MHPCO's favor", () => {
49	    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
50	    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
51	    it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
52	  });
53	
54	  describe("claim processing — standard reimbursement", () => {
55	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
56	    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
57	  });
58	
59	  describe("claim processing — special clauses", () => {
60	    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
61	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
62	    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
