69	
70	  describe("multiple items of the same type", () => {
71	    it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
72	    it.todo("two sword damage entries against a two-sword policy → each treated as a separate damage with its own deductible");
73	    it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → error, non-zero exit");
